Q: Given an array return any index on which its dominator occurs A: <p>The first your function presented in the question is evidently wrong.</p>
<p>It returns nothing. The variable <strong>cnt</strong> is not reseted to <strong>1</strong> for next new element of the array. And the if statement with the <strong>break</strong> statement within the inner for loop</p>
<pre><code>        for(j=i+1;j&lt;N;j++)
        {
            if(A[i] == A[j])
            {
                cnt++;

                i++;
                break;
            }
        }
</code></pre>
<p>does not make sense.</p>
<p>As for your second function in your own answer then first of all do not use upper case letters for identifiers.  Variables should be declared in minimum scopes where they are used. The first parameter shall be specified with the qualifier <strong>const</strong> while the second parameter shall have type <strong>size_t</strong>.  That is the function itself should be declared the following way</p>
<pre><code>size_t array_dominator( const int a[], size_t n );
</code></pre>
<p>Dynamically allocation of memory for an auxiliary array or using a variable length array makes your function unsafe. Also you forgot to free the dynamically allocated array within the function.</p>
<p>I would define the function the following way as sjown in the demonstration program below.</p>
<pre><code>#include &lt;stdio.h&gt;

size_t array_dominator( const int a[], size_t n )
{
    size_t index = -1;
    size_t dominant = n / 2 + 1;

    for ( size_t i = 0, n1 = n / 2 + n % 2; index == ( size_t )-1 &amp;&amp; i &lt; n1; i++ )
    {
        size_t count = 1;

        for ( size_t j = i + 1; count &lt; dominant &amp;&amp; dominant - count &lt; n - j + 1; j++ )
        {
            if ( a[j] == a[i] ) ++count;

        }

        if ( count == dominant ) index = i;
    }

    return index;
}

int main(void) 
{
    for( size_t i = 0, n = 5; i &lt; n; i++ )
    {
        size_t index = -1;
        int dominator;

        switch ( i )
        {
            case 0:
            {
                int a[] = { 1 };
                const size_t N = sizeof( a ) / sizeof( *a );
                printf( &quot;a = { &quot; );
                for ( size_t j = 0; j &lt; N; j++ )
                {
                    if ( j != 0 ) printf( &quot;, &quot; );
                    printf( &quot;%d&quot;, a[j] );
                }
                puts( &quot; }&quot; );

                index = array_dominator( a, N );
                if ( index != ( size_t )-1 ) dominator = a[index];
                break;
            }

            case 1:
            {
                int a[] = { 1, 1 };
                const size_t N = sizeof( a ) / sizeof( *a );
                printf( &quot;a = { &quot; );
                for ( size_t j = 0; j &lt; N; j++ )
                {
                    if ( j != 0 ) printf( &quot;, &quot; );
                    printf( &quot;%d&quot;, a[j] );
                }
                puts( &quot; }&quot; );

                index = array_dominator( a, N );
                if ( index != ( size_t )-1 ) dominator = a[index];
                break;
            }

            case 2:
            {
                int a[] = { 1, 2 };
                const size_t N = sizeof( a ) / sizeof( *a );
                printf( &quot;a = { &quot; );
                for ( size_t j = 0; j &lt; N; j++ )
                {
                    if ( j != 0 ) printf( &quot;, &quot; );
                    printf( &quot;%d&quot;, a[j] );
                }
                puts( &quot; }&quot; );

                index = array_dominator( a, N );
                if ( index != ( size_t )-1 ) dominator = a[index];
                break;
            }

            case 3:
            {
                int a[] = { 1, 2, 1 };
                const size_t N = sizeof( a ) / sizeof( *a );
                printf( &quot;a = { &quot; );
                for ( size_t j = 0; j &lt; N; j++ )
                {
                    if ( j != 0 ) printf( &quot;, &quot; );
                    printf( &quot;%d&quot;, a[j] );
                }
                puts( &quot; }&quot; );

                index = array_dominator( a, N );
                if ( index != ( size_t )-1 ) dominator = a[index];
                break;
            }

            case 4:
            {
                int a[] = { 3, 4, 3, 2, 3, -1, 3, 3 };
                const size_t N = sizeof( a ) / sizeof( *a );
                printf( &quot;a = { &quot; );
                for ( size_t j = 0; j &lt; N; j++ )
                {
                    if ( j != 0 ) printf( &quot;, &quot; );
                    printf( &quot;%d&quot;, a[j] );
                }
                puts( &quot; }&quot; );

                index = array_dominator( a, N );
                if ( index != ( size_t )-1 ) dominator = a[index];
                break;
            }
        }

        if ( index != ( size_t )-1 )
        {
            printf( &quot;The dominant element is %d at position %zu\n&quot;, dominator, index );
        }
        else
        {
            puts( &quot;There is no dominator&quot; );
        }
    }
}
</code></pre>
